def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    children = [{}]
    bad = [False]
    for p in banned:
        u = 0
        for ch in p:
            nxt = children[u].get(ch)
            if nxt is None:
                nxt = len(children)
                children[u][ch] = nxt
                children.append({})
                bad.append(False)
            u = nxt
        if u != 0:
            bad[u] = True
    m = len(children)
    fail = [0] * m
    from collections import deque
    q = deque(children[0].values())
    while q:
        u = q.popleft()
        bad[u] = bad[u] or bad[fail[u]]
        for ch, v in children[u].items():
            f = fail[u]
            while f and ch not in children[f]:
                f = fail[f]
            fail[v] = children[f][ch] if ch in children[f] else 0
            q.append(v)
    good = [i for i in range(m) if not bad[i]]
    index = {s: i for i, s in enumerate(good)}
    g = len(good)

    def nxt_state(u, ch):
        while u and ch not in children[u]:
            u = fail[u]
        return children[u][ch] if ch in children[u] else 0

    mat = [[0] * g for _ in range(g)]
    for s in good:
        i = index[s]
        for ch in alphabet:
            t = nxt_state(s, ch)
            if not bad[t]:
                mat[i][index[t]] += 1

    def mul(a, b):
        c = [[0] * g for _ in range(g)]
        for i in range(g):
            for k in range(g):
                aik = a[i][k]
                if aik:
                    bk = b[k]
                    ci = c[i]
                    for j in range(g):
                        ci[j] = (ci[j] + aik * bk[j]) % MOD
        return c

    def mpow(a, e):
        r = [[1 if i == j else 0 for j in range(g)] for i in range(g)]
        while e:
            if e & 1:
                r = mul(r, a)
            a = mul(a, a)
            e >>= 1
        return r

    res = mpow(mat, n)
    return sum(res[index[0]]) % MOD
